package server

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"net/http"
)

// avatarsJSON is the board-avatar art: per fighter, its palette and one compact set of
// SVG paths cut to the app's headshot crop (with and without the pirate hat). Generated by
// cmd/avatarbake from the fighter art the app ships; never edited by hand.
//
//go:embed static/board-avatars.json
var avatarsJSON []byte

// avatarsURL is content-addressed, so the page can cache it forever and a new bake is a
// new URL. The page script carries it (see boardScript).
var avatarsURL = func() string {
	sum := sha256.Sum256(avatarsJSON)
	return "/assets/board-avatars-" + hex.EncodeToString(sum[:6]) + ".json"
}()

// handleAvatars serves the art at avatarsURL only; any other name is the JSON 404.
func handleAvatars(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != avatarsURL {
		handleNotFound(w, r)
		return
	}
	h := w.Header()
	h.Set("Content-Type", "application/json")
	h.Set("Cache-Control", "public, max-age=31536000, immutable")
	_, _ = w.Write(avatarsJSON)
}
